# Code generated by Claude
"""The VLA's instruction, built from resolved fields (design plan 8, decisions-log M169).

    text = build_instruction("pick", {"manipulated": "beaker"})                          # "pick up the beaker"
    text = build_instruction("place", {"manipulated": "beaker", "destination": "hotplate"})   # "place the beaker on the hotplate"

After grounding, the manipulation interface gets an instruction made from a template, the step's primitive and the NAMES of the grounded world-model entries; the LLM's description is not passed
on (it is still logged and still goes to the VLM checker with the completion criterion). Reason (David, 2026-10-23): a phrase such as "its original location" means nothing to a VLA that only
sees the current images, so the instruction names only things the world model knows. The templates are one config block (task_config.INSTRUCTION_CFG) and this one function, which the demo
generator (B4) reuses so that the training prompts and the runtime prompts are the same text. If a needed object or destination is missing the step stops with "instruction cannot be grounded:
<phrase>".

Contents:
    InstructionError, build_instruction.
"""

from src.task_config import INSTRUCTION_CFG


class InstructionError(ValueError):
    """A needed object or destination has no name: the instruction cannot be built."""


def build_instruction(primitive, names, templates=None):
    """Builds the instruction of a manipulation step.

    Args:
        primitive (str): "pick" or "place" (the planner's primitive).
        names (dict): {role: name} of the grounded entries, role "manipulated" (the object) and, for a place, "destination". The name is the world-model entry's name ("beaker").
        templates (dict or None): {primitive: template with {object} and {destination}}. Defaults to INSTRUCTION_CFG["templates"].

    Returns:
        str: The instruction.

    Raises:
        InstructionError: If the primitive has no template, or a role the template needs has no name ("instruction cannot be grounded: <what is missing>").
    """
    templates = templates or INSTRUCTION_CFG["templates"]
    if primitive not in templates:
        raise InstructionError(f"instruction cannot be grounded: no template for the primitive {primitive!r}")
    fields = {"object": names.get("manipulated"), "destination": names.get("destination")}
    for needed in ("object", "destination"):
        if "{" + needed + "}" in templates[primitive] and not (fields[needed] and str(fields[needed]).strip()):
            raise InstructionError(f"instruction cannot be grounded: the {needed} of the {primitive} step has no name")
    return templates[primitive].format(**{k: str(v).strip() for k, v in fields.items() if v})
